// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Status code.
*
* ## Notes
*
* The status code indicates the following conditions:
*
* -   if equal to zero, then the matrix `Q` was generated successfully
*/
type StatusCode = number;


/**
* Interface describing `dorglq`.
*/
interface Routine {
	/**
	* Generates an `M-by-N` real orthogonal matrix `Q` from the elementary reflectors returned by `DGELQF`.
	*
	* ## Notes
	*
	* -   On entry, the i-th row must contain the vector which defines the elementary reflector `H(i)`, for `i = 1,2,...,K`, as returned by `DGELQF` in the first `K` rows of its array argument `A`.
	* -   On exit, the `M-by-N` orthogonal matrix `Q`.
	* -   `WORK` must have length, `LWORK >= max(1,M)`. For optimum performance `LWORK >= M*NB`.
	*
	* @param order - storage layout
	* @param M - number of rows of `Q`
	* @param N - number of columns of `Q`
	* @param K - number of elementary reflectors
	* @param A - input/output matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param TAU - scalar factors of the elementary reflectors
	* @param WORK - workspace array
	* @param LWORK - dimension of the array `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1, 0, 0, -1, -2, 0 ] );
	* var TAU = new Float64Array( [ 1, 1 ] );
	* var WORK = new Float64Array( 10 );
	*
	* dorglq( 'column-major', 2, 3, 2, A, 2, TAU, WORK, 10 );
	* // A => <Float64Array>[ 0, 0, 0, 0, 2, 0 ]
	*/
	( order: Layout, M: number, N: number, K: number, A: Float64Array, LDA: number, TAU: Float64Array, WORK: Float64Array, LWORK: number ): StatusCode;

	/**
	* Generates an `M-by-N` real orthogonal matrix `Q` from the elementary reflectors returned by `DGELQF` using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   On entry, the i-th row must contain the vector which defines the elementary reflector `H(i)`, for `i = 1,2,...,K`, as returned by `DGELQF` in the first `K` rows of its array argument `A`.
	* -   On exit, the `M-by-N` orthogonal matrix `Q`.
	* -   `WORK` must have length, `LWORK >= max(1,M)`. For optimum performance `LWORK >= M*NB`.
	*
	* @param M - number of rows of `Q`
	* @param N - number of columns of `Q`
	* @param K - number of elementary reflectors
	* @param A - input/output matrix
	* @param strideA1 - stride length for the first dimension of `A`
	* @param strideA2 - stride length for the second dimension of `A`
	* @param offsetA - starting index of `A`
	* @param TAU - scalar factors of the elementary reflectors
	* @param strideTAU - stride length for `TAU`
	* @param offsetTAU - starting index of `TAU`
	* @param WORK - workspace array
	* @param strideWORK - stride length for `WORK`
	* @param offsetWORK - starting index of `WORK`
	* @param LWORK - dimension of the array `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1, 0, 0, -1, -2, 0 ] );
	* var TAU = new Float64Array( [ 1, 1 ] );
	* var WORK = new Float64Array( 10 );
	*
	* dorglq.ndarray( 2, 3, 2, A, 1, 2, 0, TAU, 1, 0, WORK, 1, 0, 10 );
	* // A => <Float64Array>[ 0, 0, 0, 0, 2, 0 ]
	*/
	ndarray( M: number, N: number, K: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, TAU: Float64Array, strideTAU: number, offsetTAU: number, WORK: Float64Array, strideWORK: number, offsetWORK: number, LWORK: number ): StatusCode;
}

/**
* LAPACK routine to generate an `M-by-N` real orthogonal matrix `Q` from the elementary reflectors returned by `DGELQF`.
*
* ## Notes
*
* -   On entry, the i-th row must contain the vector which defines the elementary reflector `H(i)`, for `i = 1,2,...,K`, as returned by `DGELQF` in the first `K` rows of its array argument `A`.
* -   On exit, the `M-by-N` orthogonal matrix `Q`.
* -   `WORK` must have length, `LWORK >= max(1,M)`. For optimum performance `LWORK >= M*NB`.
*
* @param order - storage layout
* @param M - number of rows of `Q`
* @param N - number of columns of `Q`
* @param K - number of elementary reflectors
* @param A - input/output matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param TAU - scalar factors of the elementary reflectors
* @param WORK - workspace array
* @param LWORK - dimension of the array `WORK`
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 0, 0, -1, -2, 0 ] );
* var TAU = new Float64Array( [ 1, 1 ] );
* var WORK = new Float64Array( 10 );
*
* dorglq( 'column-major', 2, 3, 2, A, 2, TAU, WORK, 10 );
* // A => <Float64Array>[ 0, 0, 0, 0, 2, 0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 0, 0, -1, -2, 0 ] );
* var TAU = new Float64Array( [ 1, 1 ] );
* var WORK = new Float64Array( 10 );
*
* dorglq.ndarray( 2, 3, 2, A, 1, 2, 0, TAU, 1, 0, WORK, 1, 0, 10 );
* // A => <Float64Array>[ 0, 0, 0, 0, 2, 0 ]
*/
declare var dorglq: Routine;


// EXPORTS //

export = dorglq;
